const CSS=`
.hero-bg{background-size:cover!important;background-position:center!important}
.hx-h1{text-shadow:0 2px 6px rgba(0,0,0,.5),0 4px 30px rgba(0,0,0,.6)}
.hx-w{display:inline-block;margin-right:.26em;opacity:0;transform:translateY(40px) rotateX(-40deg);filter:blur(10px);animation:hxIn .9s cubic-bezier(.2,.8,.2,1) forwards}
.hx-gold{background:linear-gradient(100deg,#b8861b 0%,#f5d77a 35%,#d4a72c 55%,#fff1b8 75%,#b8861b 100%);background-size:250% 100%;-webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-fill-color:transparent;text-shadow:none;animation:hxIn .9s cubic-bezier(.2,.8,.2,1) forwards,hxShine 4s linear 1.2s infinite}
.hx-line{display:block;height:3px;width:0;margin:18px 0 20px;border-radius:3px;background:linear-gradient(90deg,#d4a72c,rgba(212,167,44,0));animation:hxLine 1s ease .9s forwards}
.hx-lead,.hx-btns{opacity:0;transform:translateY(18px);animation:hxFade .8s ease forwards}
.hx-lead{animation-delay:1.1s;text-shadow:0 2px 14px rgba(0,0,0,.6)}
.hx-btns{animation-delay:1.35s}
@keyframes hxIn{to{opacity:1;transform:none;filter:blur(0)}}
@keyframes hxShine{to{background-position:-250% 0}}
@keyframes hxLine{to{width:120px}}
@keyframes hxFade{to{opacity:1;transform:none}}
html{scroll-behavior:smooth}
section[id]{scroll-margin-top:90px}
.tm-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:24px}
.tm-card{background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.1);border-radius:24px;overflow:hidden;transition:border-color .25s,transform .25s}
.tm-card:hover{border-color:#d4a72c;transform:translateY(-4px)}
.tm-photo{position:relative;aspect-ratio:4/5;background-size:cover;background-position:center top}
.tm-exp{position:absolute;left:14px;bottom:14px;display:inline-flex;align-items:center;gap:6px;padding:7px 14px;border-radius:999px;font-size:13px;font-weight:500;color:#f5efe6;
background:rgba(10,10,11,.55);border:1px solid rgba(212,167,44,.55);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px)}
.tm-exp svg{color:#d4a72c}
.tm-body{padding:20px 24px 26px}
.tm-ico{color:#d4a72c;font-size:20px;margin-bottom:8px}
.tm-body h3{font-size:21px;margin-bottom:4px}
.tm-body p{font-weight:300}
.tm-body small{display:block;margin-top:10px;color:#d4a72c;letter-spacing:.04em}
.c .btn+.btn{margin-left:12px}
.hc-group{margin-bottom:40px}
.hc-group h3{font-size:24px;margin-bottom:16px;padding-bottom:10px;border-bottom:1px solid rgba(255,255,255,.1)}
.hc-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(110px,1fr));gap:18px}
.hc-sw{background:none;border:0;padding:0;font:inherit;color:inherit;cursor:pointer;text-align:center;-webkit-tap-highlight-color:transparent}
.hc-dot{position:relative;display:block;margin-bottom:8px}
.hc-dot i{display:block;aspect-ratio:1;border-radius:50%;border:2px solid rgba(255,255,255,.15);box-shadow:0 8px 20px rgba(0,0,0,.5);transition:transform .25s,box-shadow .25s,border-color .25s}
.hc-sw:hover .hc-dot i{transform:scale(1.05);border-color:rgba(212,167,44,.6)}
.hc-sw:focus-visible .hc-dot i{outline:2px solid #d4a72c;outline-offset:4px}
.hc-sw.on .hc-dot i{transform:scale(1.07);border-color:#d4a72c;box-shadow:0 0 0 3px #0a0a0b,0 0 0 5px #d4a72c,0 10px 26px rgba(212,167,44,.35)}
.hc-tick{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);font-size:26px;color:#fff;filter:drop-shadow(0 2px 6px rgba(0,0,0,.6));pointer-events:none}
.hc-name{display:block;font-size:14px;font-weight:300;transition:color .25s}
.hc-sw.on .hc-name{color:#d4a72c;font-weight:500}
.hc-bar{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-top:8px;padding:16px 22px;border-radius:20px;background:rgba(255,255,255,.04);border:1px solid rgba(212,167,44,.4);opacity:0;transform:translateY(8px);pointer-events:none;transition:opacity .3s,transform .3s}
.hc-bar.show{opacity:1;transform:none;pointer-events:auto}
.hc-bar b{color:#d4a72c}
.gl-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:20px}
.gl-tile{transition:transform .3s}.gl-tile:hover{transform:scale(1.02)}
.gl-tile{position:relative;aspect-ratio:4/5;border-radius:22px;overflow:hidden;border:1px solid rgba(255,255,255,.1);background-size:cover;background-position:center}
.gl-tile span{position:absolute;left:0;right:0;bottom:0;padding:48px 20px 18px;font-weight:500;background:linear-gradient(transparent,rgba(0,0,0,.8))}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}.tm-card{transition:none}.hc-dot i,.hc-bar{transition:none}.hx-w,.hx-gold,.hx-lead,.hx-btns,.hx-line{animation:none!important;opacity:1;transform:none;filter:none;width:120px}.hx-line{width:120px}}
`;

