<section className="wrap"><Head k="Why us" t="The SS Difference"/><Cards items={[[FaHandshake,"Polite Staff","Clients mention our friendly, professional team."],[FaLightbulb,"Honest Suggestions","Haircut advice that suits you."],[FaBroom,"Clean & Cozy","Premium ambience, hygienic setup."]]}/></section>

